const texto = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;

// /prazo → todos os pendentes
// /prazo Maria → filtra por cliente
// /prazo urgente → filtra por urgência
// /prazo 0001234 → filtra por processo

const partes = texto.split(' ').slice(1);
const filtro = partes.join(' ').trim();

let tipo_filtro = 'todos';
if (filtro) {
  if (['critica', 'alta', 'media', 'baixa', 'urgente'].includes(filtro.toLowerCase())) {
    tipo_filtro = 'urgencia';
  } else if (/\d{5,}/.test(filtro)) {
    tipo_filtro = 'processo';
  } else {
    tipo_filtro = 'cliente';
  }
}

return [{json: {
  filtro,
  tipo_filtro,
  chat_id: chatId
}}];

const prazos = $input.all().map(i => i.json);
const filtro = $('Extrair Filtro').first().json.filtro;
const tipo = $('Extrair Filtro').first().json.tipo_filtro;
const chatId = $('Extrair Filtro').first().json.chat_id;

let filtrados = prazos.filter(p => p.STATUS === 'pendente');

// Aplica filtro
if (tipo === 'cliente' && filtro) {
  filtrados = filtrados.filter(p =>
    (p.CLIENTE || '').toLowerCase().includes(filtro.toLowerCase())
  );
} else if (tipo === 'urgencia') {
  const urg = filtro.toLowerCase() === 'urgente' ? ['critica', 'alta'] : [filtro.toLowerCase()];
  filtrados = filtrados.filter(p => urg.includes((p.URGENCIA || '').toLowerCase()));
} else if (tipo === 'processo' && filtro) {
  filtrados = filtrados.filter(p =>
    (p.PROCESSO || '').includes(filtro)
  );
}

// Ordena por data limite
filtrados.sort((a, b) => {
  const dA = new Date(a.DATA_LIMITE || '2099-12-31');
  const dB = new Date(b.DATA_LIMITE || '2099-12-31');
  return dA - dB;
});

// Formata mensagem
let msg = '';

if (filtrados.length === 0) {
  msg = '📭 Nenhum prazo pendente encontrado';
  if (filtro) msg += ' para "' + filtro + '"';
  msg += '.';
} else {
  const icones = {
    critica: '🔴',
    alta: '🟠',
    media: '🟡',
    baixa: '🟢'
  };

  msg = '📋 *PRAZOS PENDENTES*';
  if (filtro) msg += ' — ' + filtro;
  msg += '\n\n';

  filtrados.slice(0, 10).forEach((p, i) => {
    const icone = icones[p.URGENCIA] || '⚪';
    msg += icone + ' *' + (p.TIPO_ATO || 'Ato').toUpperCase() + '*\n';
    msg += '  📋 `' + (p.PROCESSO || 'N/A') + '`\n';
    msg += '  👤 ' + (p.CLIENTE || 'N/A') + '\n';
    msg += '  📅 Vencimento: ' + (p.DATA_LIMITE || 'N/A') + '\n';
    msg += '  ✏️ ' + (p.ACAO || 'N/A') + '\n\n';
  });

  if (filtrados.length > 10) {
    msg += '... e mais ' + (filtrados.length - 10) + ' prazos.';
  }

  msg += '\n_Total: ' + filtrados.length + ' prazo(s) pendente(s)_';
}

return [{json: {msg, chat_id: chatId, total: filtrados.length}}];
